import {businessWarrantyAssessmentSchema} from '../../api/business-ontology';
import {policyDraft,policyComparison} from './business-policy';
export function warrantyAssessment(){const p=policyDraft(),comparison=policyComparison();return businessWarrantyAssessmentSchema.parse({assessment_version:'simpson-warranty-assessment-v1',version_id:'v2',graph_id:'g1',policy_id:p.policy_id,policy_revision:p.revision,ticket_node_id:'node1',invoice_node_id:null,assessment_at:'2026-06-01T12:00:00+05:30',classification:'Requires Review',draft_calculation:'incomplete_evidence',checks:[{check_id:'operating_hours',status:'unknown',message:'Primary complaint hours are missing; no alternate hours substituted.',observed:null,expected:{max_hours:'1000',boundary:'inclusive'},evidence:[],clause_ids:['max_hours','hours_boundary']},{check_id:'exclusion:misuse_check',status:'unknown',message:'No verified exclusion finding is available.',observed:null,expected:'Verified exclusion finding',evidence:[],clause_ids:['exclusion_checks']}],blockers:[{code:'POLICY_AUTHORITY_UNVERIFIED',message:'The selected policy is a cited draft with unverified authority.'},{code:'PHYSICAL_IDENTITY_UNRESOLVED',message:'Physical-engine identity is unresolved.'},{code:'REQUIRED_EVIDENCE_UNKNOWN',message:'Required complaint hours or exclusion evidence are unavailable.'}],policy_clauses:p.clauses,policy_source:comparison.policy_source,applicability_checks:comparison.checks,physical_engine_identity:'unresolved',business_policy_verified:false,eligibility_final:false,provenance:{...comparison.provenance,association_report_sha256:'associationshash',reference_basis_sha256:'basishash'},limits:['Draft calculations are not approval or denial.','No company record or eligibility decision was written.'],company_queries:0,model_calls:0,coverage_calculations_performed:false,business_rules_executed:false,report_sha256:'assessmenthash'});}
export function missingPolicyAssessment(){const report=warrantyAssessment();return businessWarrantyAssessmentSchema.parse({...report,policy_id:null,policy_revision:null,policy_clauses:{},policy_source:null,applicability_checks:[],blockers:[{code:'POLICY_MISSING',message:'No warranty policy is selected. Missing policy requires review, not approval or denial.'}],provenance:{...report.provenance,policy_sha256:null,policy_source_sha256:null}});}
